/**
 * @param {number} n
 * @return {number}
 */
var binaryGap = function(n) {
    const bin = n.toString(2);
    let last = -1;
    let res = 0;

    for (let i = 0; i < bin.length; i++) {
        if (bin[i] === '0') {
            continue;
        }

        if (last > -1) {
            res = Math.max(res, i - last);
        }

        last = i;
    }

    return res;
};
